fn main() {
    // ---- Clone (explicit, deep copy) ----
    let s1 = String::from("hello");
    let s2 = s1.clone();  // Deep copy
    println!("s1: {}, s2: {}", s1, s2);  // Both valid

    // ---- Copy (implicit, shallow) ----
    let x = 5;
    let y = x;  // Copy
    println!("x: {}, y: {}", x, y);  // Both valid

    // ---- Types that implement Copy ----
    // Integers: i8, i16, i32, i64, i128, isize
    // Unsigned: u8, u16, u32, u64, u128, usize
    // Floats: f32, f64
    // Boolean: bool
    // Characters: char
    // Tuples of Copy types: (i32, i32) is Copy
    // Tuples with non-Copy types: NOT Copy

    // ---- Types that do NOT implement Copy ----
    // String
    // Vec
    // Box
    // Most custom types

    // ---- Deriving Copy for custom types ----
    #[derive(Copy, Clone)]
    struct Point {
        x: i32,
        y: i32,
    }

    let p1 = Point { x: 10, y: 20 };
    let p2 = p1;  // Copy (because Point derives Copy)
    println!("p1: ({}, {}), p2: ({}, {})", p1.x, p1.y, p2.x, p2.y);

    // ---- Deriving Clone for custom types ----
    #[derive(Clone)]
    struct Player {
        name: String,
        health: i32,
    }

    let player1 = Player {
        name: String::from("Hero"),
        health: 100,
    };
    let player2 = player1.clone();  // Clone
    println!("player1: {}, player2: {}", player1.name, player2.name);

    // ---- When to use Clone ----
    let s = String::from("hello");
    let t = s.clone();  // Use clone when you need both
    // Without clone, s would be moved

    // ---- Clone can be expensive ----
    // It copies all data on the heap
    // Use it sparingly, especially for large data
}

